    <title>Computer Languages Quiz</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --card: #ffffff;
        --text: #122033;
        --muted: #5f6b7a;
        --line: #dbe3ee;
        --accent: #2563eb;
        --accent-soft: #eaf1ff;
        --shadow: 0 20px 50px rgba(18, 32, 51, 0.08);
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top left, rgba(37, 99, 235, 0.12), transparent 30%),
          radial-gradient(circle at top right, rgba(14, 165, 233, 0.1), transparent 25%),
          var(--bg);
        color: var(--text);
      }

      .page {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 32px 16px;
      }

      .quiz-shell {
        width: min(760px, 100%);
        background: var(--card);
        border: 1px solid rgba(219, 227, 238, 0.8);
        border-radius: calc(var(--radius) + 4px);
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .quiz-header {
        padding: 32px 32px 20px;
        border-bottom: 1px solid var(--line);
        background: linear-gradient(180deg, rgba(37, 99, 235, 0.05), transparent);
      }

      .eyebrow {
        margin: 0 0 10px;
        color: var(--accent);
        font-size: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(1.8rem, 3vw, 2.5rem);
        line-height: 1.1;
      }

      .subtitle {
        margin: 12px 0 0;
        color: var(--muted);
        max-width: 58ch;
      }

      form {
        padding: 28px 32px 32px;
      }

      .form-field {
        padding: 22px;
        border: 1px solid var(--line);
        border-radius: 18px;
        background: #fbfcff;
        margin-bottom: 18px;
      }

      .question-title {
        margin: 0 0 8px;
        font-size: 1.05rem;
      }

      .help-text {
        margin: 0 0 16px;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .options {
        display: grid;
        gap: 12px;
      }

      .option {
        display: flex;
        gap: 12px;
        align-items: flex-start;
        padding: 14px 16px;
        border: 1px solid var(--line);
        border-radius: 14px;
        background: #fff;
        transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
      }

      .option:hover {
        border-color: rgba(37, 99, 235, 0.35);
        box-shadow: 0 10px 24px rgba(37, 99, 235, 0.08);
        transform: translateY(-1px);
      }

      .option input {
        margin-top: 2px;
        accent-color: var(--accent);
        width: 18px;
        height: 18px;
        flex: 0 0 auto;
      }

      .option span {
        line-height: 1.45;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        padding-top: 6px;
      }

      .submit-btn {
        appearance: none;
        border: 0;
        border-radius: 999px;
        background: var(--accent);
        color: #fff;
        font-weight: 700;
        padding: 14px 22px;
        font-size: 1rem;
        cursor: pointer;
        box-shadow: 0 14px 28px rgba(37, 99, 235, 0.24);
      }

      .submit-btn:hover {
        background: #1d4ed8;
      }

      .result {
        margin-top: 14px;
        padding: 14px 16px;
        border-radius: 14px;
        background: var(--accent-soft);
        color: #12316b;
        display: none;
      }

      .result.visible {
        display: block;
      }

      @media (max-width: 640px) {
        .quiz-header,
        form {
          padding-left: 18px;
          padding-right: 18px;
        }

        .form-field {
          padding: 18px;
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>

    <script>
      const questions = [
        {
          id: "languages-foundations",
          title: "Which of these are programming languages?",
          helpText: "Select every option that is a computer programming language.",
          options: ["Python", "HTML", "JavaScript", "CSS"],
        },
        {
          id: "typed-languages",
          title: "Which of these are statically typed languages?",
          options: ["Go", "Ruby", "TypeScript", "Rust"],
        },
        {
          id: "oldest-languages",
          title: "Which of these languages have been widely used for decades?",
          options: ["C", "COBOL", "Swift", "FORTRAN"],
        },
      ];

      function Question({ question, index }) {
        const help = question.helpText
          ? `<p class="help-text">${question.helpText}</p>`
          : "";
        const options = question.options
          .map(
            (option, optionIndex) => `
              <label class="option">
                <input
                  type="checkbox"
                  name="${question.id}"
                  value="${option}"
                  aria-label="${option}"
                />
                <span>${option}</span>
              </label>
            `
          )
          .join("");

        return `
          <div class="form-field">
            <h2 class="question-title">${index + 1}. ${question.title}</h2>
            ${help}
            <div class="options" role="group" aria-label="${question.title}">
              ${options}
            </div>
          </div>
        `;
      }

      function App() {
        return `
          <main class="page">
            <section class="quiz-shell" aria-labelledby="quiz-title">
              <header class="quiz-header">
                <p class="eyebrow">Knowledge Check</p>
                <h1 id="quiz-title">Computer Languages Quiz</h1>
                <p class="subtitle">
                  Choose all answers that apply for each question. This quiz uses multiple-select checkboxes for every prompt.
                </p>
              </header>

              <form id="quiz-form">
                ${questions.map((question, index) => Question({ question, index })).join("")}
                <div class="actions">
                  <button class="submit-btn" type="submit">Submit quiz</button>
                </div>
                <div id="result" class="result" aria-live="polite"></div>
              </form>
            </section>
          </main>
        `;
      }

      document.getElementById("root").innerHTML = App();

      document.getElementById("quiz-form").addEventListener("submit", (event) => {
        event.preventDefault();
        const result = document.getElementById("result");
        result.textContent = "Quiz submitted.";
        result.classList.add("visible");
      });
    </script>
  </body>
</html>
