           ? `<p class="help-text">${question.helpText}</p>`
           : "";
         const options = question.options
           .map(
             (option, optionIndex) => `
               <label class="option">
                 <input
                   type="checkbox"
                   name="${question.id}"
                   value="${option}"
                   aria-label="${option}"
                 />
                 <span>${option}</span>
               </label>
             `
           )
           .join("");

         return `
           <div class="form-field">
             <h2 class="question-title">${index + 1}. ${question.title}</h2>
             ${help}
             <div class="options" role="group" aria-label="${question.title}">
               ${options}
             </div>
           </div>
         `;
       }

       function App() {
         return `
           <main class="page">
             <section class="quiz-shell" aria-labelledby="quiz-title">
               <header class="quiz-header">
                 <p class="eyebrow">Knowledge Check</p>
                 <h1 id="quiz-title">Computer Languages Quiz</h1>
                 <p class="subtitle">
                   Choose all answers that apply for each question. This quiz uses multiple-select checkboxes for every prompt.
                 </p>
               </header>

               <form id="quiz-form">
                 ${questions.map((question, index) => Question({ question, index })).join("")}
                 <div class="actions">
                   <button class="submit-btn" type="submit">Submit quiz</button>
                 </div>
                 <div id="result" class="result" aria-live="polite"></div>
               </form>
             </section>
           </main>
         `;
       }

       document.getElementById("root").innerHTML = App();

       document.getElementById("quiz-form").addEventListener("submit", (event) => {
         event.preventDefault();
         const result = document.getElementById("result");
         result.textContent = "Quiz submitted.";
         result.classList.add("visible");
       });
     </script>
   </body>
 </html>

')
